<?php
require __DIR__.'/_bootstrap.php';
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$id=filter_var($_POST['group_id']??'',FILTER_VALIDATE_INT,['options'=>['min_range'=>1]])?:0;try{$pdo->beginTransaction();$q=$pdo->prepare('SELECT booking_group_id,status FROM booking_groups WHERE booking_group_id=? FOR UPDATE');$q->execute([$id]);$g=$q->fetch();if(!$g||$g['status']!=='Confirmed')throw new RuntimeException('Booking is no longer active.');$q=$pdo->prepare('UPDATE bookings SET status="Cancelled",seat_id=NULL,cancelled_at=NOW() WHERE booking_group_id=? AND status="Confirmed"');$q->execute([$id]);$q=$pdo->prepare('UPDATE booking_groups SET status="Cancelled",active_host_user_id=NULL,cancelled_at=NOW() WHERE booking_group_id=?');$q->execute([$id]);$pdo->commit();flash('Booking cancelled and seats released.');}catch(Throwable $exception){if($pdo->inTransaction())$pdo->rollBack();flash($exception instanceof RuntimeException?$exception->getMessage():'Could not cancel booking.');}go('admin/bookings.php');}
$rows=$pdo->query('SELECT g.booking_group_id,g.booking_ref,g.journey_date,g.status,g.booking_time,u.full_name AS host,u.email,t.train_name,r.route_name,o.station_name AS origin_name,d.station_name AS destination_name,sc.departure_time FROM booking_groups g JOIN users u ON u.user_id=g.host_user_id JOIN schedules sc ON sc.schedule_id=g.schedule_id JOIN trains t ON t.train_id=sc.train_id JOIN routes r ON r.route_id=sc.route_id JOIN stations o ON o.station_id=r.origin_station_id JOIN stations d ON d.station_id=r.destination_station_id ORDER BY g.booking_time DESC LIMIT 300')->fetchAll();$pass=$pdo->prepare('SELECT passenger_name,category,gender,seat_label,bogie_label,status,is_guest FROM bookings WHERE booking_group_id=? ORDER BY is_guest');$pageTitle='All bookings';require __DIR__.'/../includes/header.php';?>
<section class="content"><span class="eyebrow">BOOKING RECORDS</span><h1>All bookings</h1><div class="list"><?php foreach($rows as $row):$pass->execute([$row['booking_group_id']]);?><article><div><span class="tag"><?=e($row['status'])?> · <?=e($row['booking_ref'])?></span><h3><?=e($row['host'])?> · <?=e($row['email'])?></h3><p><?=e($row['train_name'])?> · <?=e($row['origin_name'])?> → <?=e($row['destination_name'])?> · <?=e($row['journey_date'])?> <?=e(substr($row['departure_time'],0,5))?></p><?php foreach($pass as $p):?><p><?=e($p['is_guest']?'Guest ':'Passenger ')?><?=e($p['passenger_name'])?> · <?=e($p['category'])?>/<?=e($p['gender'])?> · <?=e($p['bogie_label'])?>/<?=e($p['seat_label'])?> · <?=e($p['status'])?></p><?php endforeach?></div><?php if($row['status']==='Confirmed'):?><form method="post"><?php csrf_input();?><input type="hidden" name="group_id" value="<?=e($row['booking_group_id'])?>"><button class="button pale">Cancel booking</button></form><?php endif?></article><?php endforeach?><?php if(!$rows):?><article>No bookings found.</article><?php endif?></div></section>
<?php require __DIR__.'/../includes/footer.php'; ?>
